svg.script:
(function(){
  var svg=document.documentElement, btn=document.getElementById('pause-control');
  function setPaused(paused){
    if(paused){svg.pauseAnimations();}else{svg.unpauseAnimations();}
    document.getElementById('pause-label').textContent=paused?'Play':'Pause';
    document.getElementById('pause-icon').setAttribute('d',paused?'M48 1000 L57 1007 L48 1014 Z':'M49 1000 V1013 M55 1000 V1013');
    btn.setAttribute('aria-label',paused?'Play animation':'Pause animation');
  }
  function toggle(){setPaused(!svg.animationsPaused());}
  function replay(){svg.setCurrentTime(0);setPaused(false);}
  btn.addEventListener('click',toggle);
  document.getElementById('replay-control').addEventListener('click',replay);
  [btn,document.getElementById('replay-control')].forEach(function(b){b.addEventListener('keydown',function(e){if(e.key==='Enter'){e.preventDefault();b.dispatchEvent(new Event('click'));}});});
  document.addEventListener('keydown',function(e){if(e.code==='Space'){e.preventDefault();toggle();}if(e.key.toLowerCase()==='r'){replay();}});
  if(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches){svg.setCurrentTime(26);setPaused(true);}
})();
